export async function loadProviderModule(providerValue: string, fileName: string): Promise<any> {
  const provider = PROVIDER_REGISTRY[providerValue];
  if (!provider) return null;
  const loader = provider[fileName];
  if (!loader) return null;
  try {
    const mod = await loader();
    return (mod && mod.default) ? { ...mod, ...mod.default } : mod;
  } catch (err) {
    console.warn(`[ProviderRegistry] Failed to load ${providerValue}/${fileName}:`, err);
    return null;
  }
}
